static IEnumerable<TypeDefinition> All(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in All(n))yield return x;}
static uint Token(ICustomAttributeProvider p){var v=p.CustomAttributes.FirstOrDefault(a=>a.AttributeType.Name=="TokenAttribute")?.Fields.FirstOrDefault(f=>f.Name=="Token").Argument.Value as string;return v is null?0:uint.Parse(v[2..],NumberStyles.HexNumber);}
static uint SourceToken(MemberDeclarationSyntax? n){var a=n?.AttributeLists.SelectMany(x=>x.Attributes).FirstOrDefault(a=>a.Name.ToString()=="Token");return a is null?0:uint.Parse(((LiteralExpressionSyntax)a.ArgumentList!.Arguments[0].Expression).Token.ValueText[2..],NumberStyles.HexNumber);}
static string Address(MethodDefinition m)=>m.CustomAttributes.FirstOrDefault(a=>a.AttributeType.Name=="AddressAttribute")?.Fields.FirstOrDefault(f=>f.Name=="RVA").Argument.Value as string??"";
static string Hash(string path)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
static string HashText(string s)=>Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(s)));
static void CheckHash(string path,string expected){if(!Hash(path).Equals(expected,StringComparison.OrdinalIgnoreCase))throw new Exception("Source/backup/meta hash mismatch "+path);}
